@font-face {
  font-family: 'Outfit VF';
  src: url('/fonts/Outfit-VariableFont.woff2') format('woff2-variations');
  font-weight: 100 900; /* Defines the 'wght' axis range */
  font-stretch: 75% 125%; /* Defines the 'wdth' axis range */
}

body {
  font-family: 'Outfit VF', sans-serif;
  /* Default font width, typically 100 or 'normal' within the font's design space */
  font-variation-settings: 'wdth' 100;
}

/* Adjust font width for smaller screens for better text flow */
@media (max-width: 768px) {
  p {
    /* Slightly condensed text for tighter spaces */
    font-variation-settings: 'wdth' 90;
  }
}

/* Expand font width for larger, ample spaces */
.hero-headline {
  font-size: clamp(3rem, 8vw, 6rem);
  /* Broader letters for a more open, impactful headline */
  font-variation-settings: 'wdth' 120;
  line-height: 1.1;
}
